"""Reflexion (Shinn et al. 2023; noahshinn/reflexion alfworld_runs) on the ReAct actor, chat-rendered."""
from __future__ import annotations

import os
import sys

from planner_api import RESTART, Budget, LLMClient

_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "prompts")
sys.path.insert(0, _DIR)
from react_transcripts import few_shot_messages, load_prompts, merge_adjacent, parse_action, prompt_key  # noqa: E402

HEADER = 'Interact with a household to solve a task. Here are two examples.'
MAX_STEPS = 49          # `while cur_step < 49` in alfworld_run


class EnvironmentHistory:
    """env_history.py: transcript of one attempt; `exhausted` = same action twice in a row."""

    def __init__(self, start_info, memory):
        self.start_info = start_info
        self.memory = list(memory)
        self._history = []
        self._last_action = ''
        self._is_exhausted = False

    def add(self, label, value):
        assert label in ['action', 'observation']
        self._history += [{'label': label, 'value': value}]
        if label == 'action':
            if value == self._last_action:
                self._is_exhausted = True
            else:
                self._last_action = value

    def check_is_exhausted(self):
        return self._is_exhausted

    def task_user_turn(self):
        # _get_base_query: memory block, then 'Here is the task:' + start_info
        query = ''
        if len(self.memory) > 0:
            query += 'Your memory for the task below:'
            for i, m in enumerate(self.memory):
                query += f'\nTrial {i}:\n{m.strip()}'
            query += '\n'
        query += f"Here is the task:\n{self.start_info}"
        return query

    def messages(self):
        msgs = [{"role": "user", "content": self.task_user_turn()}]
        for item in self._history:
            role = "assistant" if item['label'] == 'action' else "user"
            msgs.append({"role": role, "content": item['value']})
        return msgs

    def scenario(self):
        # generate_reflections._get_scenario: everything after 'Here is the task:'
        s = self.start_info + '\n'
        for i, item in enumerate(self._history):
            s += f'> {item["value"]}' if item['label'] == 'action' else item['value']
            if i != len(self._history) - 1:
                s += '\n'
        return s.strip()


class CustomPlanner:
    def __init__(self, llm: LLMClient, task_type: str, seed: int):
        self.llm = llm
        d = load_prompts()
        with open(os.path.join(_DIR, "reflexion_few_shot_examples.txt")) as f:
            self.few_shot = f.read()
        v = prompt_key(task_type)
        self.demo_messages = few_shot_messages(HEADER, [d[f'react_{v}_1'], d[f'react_{v}_0']])
        self.memory = []

    # alfworld_trial.llm: retry at rising temperature until a >= 5 char reply
    def _llm(self):
        cur_try = 0
        while cur_try < 6:
            if self.llm.calls_left <= 0:
                return ""
            out = self.llm.chat(merge_adjacent(self.demo_messages + self.env_history.messages()), max_tokens=256,
                                temperature=cur_try * 0.2, stop=["\n"])
            text = out[0] if out else ""
            if len(text.strip()) >= 5:
                return text
            cur_try += 1
        return ""

    def reset(self, goal, initial_obs, attempt, budget):
        mem = self.memory[-3:] if len(self.memory) > 3 else self.memory
        self.env_history = EnvironmentHistory(initial_obs, mem)
        self.cur_step = 0
        self.pending = None

    def act(self, obs, admissible, history, budget):
        if self.pending is not None:
            self.env_history.add("observation", obs)
            self.pending = None
        while self.cur_step < MAX_STEPS:
            if self.llm.calls_left <= 0:
                return RESTART
            action = parse_action(self._llm())
            self.env_history.add("action", action)
            self.cur_step += 1
            if action.startswith('think:'):
                self.env_history.add("observation", 'OK.')
                if self.env_history.check_is_exhausted():
                    return RESTART
                continue
            if not action:
                return RESTART
            if self.env_history.check_is_exhausted():
                return RESTART
            self.pending = action
            return action
        return RESTART

    def attempt_finished(self, success, history, budget):
        if success or self.llm.calls_left <= 0:
            return
        mem = self.memory[-3:] if len(self.memory) > 3 else self.memory
        query = f"""You will be given the history of a past experience in which you were placed in an environment and given a task to complete. You were unsuccessful in completing the task. Do not summarize your environment, but rather think about the strategy and path you took to attempt to complete the task. Devise a concise, new plan of action that accounts for your mistake with reference to specific actions that you should have taken. For example, if you tried A and B but forgot C, then devise a plan to achieve C with environment-specific actions. You will need this later when you are solving the same task. Give your plan after "Plan". Here are two examples:

{self.few_shot}

{self.env_history.scenario()}"""
        if len(mem) > 0:
            query += '\n\nPlans from past attempts:\n'
            for i, m in enumerate(mem):
                query += f'Trial #{i}: {m}\n'
        query += '\n\nNew plan:'
        out = self.llm.chat([{"role": "user", "content": query}], max_tokens=256, temperature=0.0)
        self.memory += [out[0] if out else ""]

