"""Baseline `adaplanner`: code-style plan generation with in-plan / out-of-plan refinement.

Reference: haotiansun14/AdaPlanner@dba1876 ALFWorld/alfworld.ipynb (cells 2, 4, 5, 6, 8, 10)
and ALFWorld/prompt_GPT3.py (shipped verbatim as prompts/adaplanner_prompt_gpt3.py).
Sun et al., NeurIPS 2023 (arXiv:2305.16653), Sec. 3.2-3.3 + Table 2 (GPT-3 column).
Ported constant-for-constant: NUM_TRY=6 refinement rounds, NUM_TRY_RESET=3 (after 3
rounds resume from step 1), MAX_TOKENS=1400, temperature 0 for every query; the
`Agent` class (goto/take/put/open_receptacle/close_receptacle/clean/heat/cool/turn_on/
report, including take/put's holding guards); receptacle + task extraction regexes;
get_solution_prompt -> code_check_prompt (syntax fix) -> `formalize` replace chain ->
execute -> on error/incomplete: feedback_fix_prompt with the error message ('[4:]' of
the traceback = the exception line, or the notebook's 'executed ... but the task is not
completed' message) -> get_start_from_prompt -> first digit = resume step ->
modify_header(checkpoint) which re-injects the failed frame's locals as defaults.
The one-demonstration prompting (one example per task type) is the paper's setting.
Adaptations forced by the harness contract: the solution runs in a helper thread so
`Agent.observation` can hand each command to `act()` one at a time; `is_success` is not
observable (the harness ends an attempt on success, so a solution that returns without
the harness stopping is by construction 'not completed'); an attempt cut by the
harness (50 env steps) resets the Agent state and the counter continues; the reference
had no step cap and never reset the environment.
"""
from pathlib import Path

_FILE = "alfworld/mlsb_planner/custom_planner.py"
_END = len((Path(__file__).parent / "mlsb_planner" / "custom_planner.py").read_text().splitlines())

_CODE = '''"""AdaPlanner (Sun et al. 2023; haotiansun14/AdaPlanner ALFWorld/alfworld.ipynb)."""
from __future__ import annotations

import os
import queue
import re
import sys
import threading
import traceback
from ast import literal_eval

from planner_api import RESTART, Budget, LLMClient

_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "prompts")
if _DIR not in sys.path:
    sys.path.insert(0, _DIR)
import adaplanner_prompt_gpt3 as P  # noqa: E402  (prompt_GPT3.py of the reference, verbatim)

NUM_TRY = 6          # max number of trials for each task
NUM_TRY_RESET = 3    # after NUM_TRY_RESET trials, the agent will try to start from step 1
MAX_TOKENS = 1400
EVENT_TIMEOUT_S = 700.0   # > the harness's LLM request timeout, so a thread is never abandoned mid-request

_EXAMPLES = [
    ('pick_two_obj', P.puttwo_example), ('look_at_obj', P.examine_example),
    ('pick_and_place', P.simple_example), ('pick_clean_then_place', P.clean_example),
    ('pick_heat_then_place', P.heat_example), ('pick_cool_then_place', P.cool_example),
]


def extract_receptacles_and_task(text):
    receptacles = re.findall(r"\\b\\w+ \\d+\\b", text)
    task = re.search(r"Your task is to:.*", text).group(0)
    return receptacles, task


def extract_answers(text, markers):
    answers = []
    for i, marker in enumerate(markers):
        if i < len(markers) - 1:
            next_marker = markers[i + 1]
            pattern = fr"{re.escape(marker)}\\s*([\\s\\S]*?)\\n*{re.escape(next_marker)}"
        else:
            pattern = fr"{re.escape(marker)}\\s*([\\s\\S]*)"
        answer = re.search(pattern, text)
        if answer:
            answers.append(answer.group(1).strip())
        else:
            answers.append('Not found')
    return answers


def get_first_digit(input_string):
    match = re.search(r'\\d', input_string)
    return int(match.group()) if match else None


def modify_header(checkpoint):
    if not checkpoint:
        return 'def solution(agent, start_from=1):'
    load_checkpoint = ''
    for k, v in checkpoint.items():
        if k not in ['agent', 'start_from']:
            if type(v) == str:
                load_checkpoint += f', {k}="{v}"'
            else:
                load_checkpoint += f', {k}={v}'
    return f'def solution(agent, start_from{load_checkpoint}):'


def formalize(solution_func):
    return solution_func.replace('CD', 'cd').replace('solution(agent)', '').replace('<EOC>', '') \\
        .replace('print("Task completed successfully!")', '').replace('print(agent.report())', '') \\
        .replace('receptacles =', '# receptacles =')


def wrap_solution(response):
    # Completion-boundary handling for an open model served as a raw completion: GPT-3
    # stopped after the function, while the open instruct model keeps writing ("solution(agent)", notes,
    # another task). Keep the text from the first `def solution(` line up to the first
    # following column-0 line; a response without a def is wrapped as in the reference.
    lines = response.split('\\n')
    start = next((i for i, l in enumerate(lines) if l.startswith('def solution(')), None)
    if start is not None:
        end = next((i for i in range(start + 1, len(lines))
                    if lines[i].strip() and not lines[i].startswith((' ', '\\t'))), len(lines))
        return '\\n'.join(lines[start:end]).rstrip()
    return \'\'\'
    def solution(agent, start_from=1):
        <solution>
    \'\'\'.strip().replace('<solution>', response) if not response.startswith('def solution(agent, start_from=1):') else response


class _AttemptEnded(BaseException):
    # BaseException on purpose: a generated solution's `except Exception:` must not swallow the
    # harness ending the attempt, or the thread would keep running (and calling the LLM) after
    # the planner has moved on.
    pass


_tls = threading.local()   # the solution thread records the launch generation it belongs to


class Agent:
    """Reference Agent class; observation() hands the command to the harness through the planner."""

    def __init__(self, receptacles, planner):
        self.location = None
        self.holding = None
        self.receptacles = receptacles
        self.interaction_history = {'actions': [], 'observations': []}
        self.is_success = False
        self._planner = planner

    def add_to_history(self, action, observation):
        self.interaction_history['actions'].append(action)
        self.interaction_history['observations'].append(observation)

    def observation(self, action):
        observation = self._planner._env_step(action)
        self.add_to_history(action, observation)
        print(f'Act: {action}\\nObs: {observation}')
        return observation

    def goto(self, receptacle):
        self.location = receptacle
        return self.observation(f'go to {receptacle}')

    def take(self, object, receptacle):
        if self.holding is None:
            self.holding = object
            return self.observation(f'take {object} from {receptacle}')

    def put(self, object, receptacle):
        if self.holding == object:
            self.holding = None
            return self.observation(f'put {object} in/on {receptacle}')

    def open_receptacle(self, receptacle):
        return self.observation(f'open {receptacle}')

    def close_receptacle(self, receptacle):
        return self.observation(f'close {receptacle}')

    def clean(self, object, receptacle):
        return self.observation(f'clean {object} with {receptacle}')

    def heat(self, object, receptacle):
        return self.observation(f'heat {object} with {receptacle}')

    def cool(self, object, receptacle):
        return self.observation(f'cool {object} with {receptacle}')

    def turn_on(self, object):
        return self.observation(f'use {object}')

    def report(self):
        msg = \\
f\'\'\'The last three interactions before error were:
Act: {self.interaction_history["actions"][-3]}
Obs: {self.interaction_history["observations"][-3]}
Act: {self.interaction_history["actions"][-2]}
Obs: {self.interaction_history["observations"][-2]}
Act: {self.interaction_history["actions"][-1]}
Obs: {self.interaction_history["observations"][-1]}
I am at {self.location} and holding {self.holding}.
\'\'\'.strip()
        return msg


class CustomPlanner:
    def __init__(self, llm: LLMClient, task_type: str, seed: int):
        self.llm = llm
        self.example = next(ex for k, ex in _EXAMPLES if task_type.startswith(k))
        self.num_try = 0
        self.solution_func = None
        self.start_num = None
        self.thread = None
        self._action_q = queue.Queue()
        self._obs_q = queue.Queue()
        self._waiting = False
        self._gen = 0            # bumped whenever a solution thread is abandoned; stale threads see it
        self._pending_launch = False

    def _stale(self):
        return getattr(_tls, 'gen', self._gen) != self._gen

    # --- LLM queries (notebook `ask`: temperature 0, MAX_TOKENS) ---
    # Code prompts (solution generation, syntax check, refinement, resume step) are
    # Python-file-style completions, served as raw completions like the GPT-3 reference.
    def ask(self, prompt):
        if self._stale():
            raise _AttemptEnded()
        return self.llm.complete(prompt.strip(), max_tokens=MAX_TOKENS, temperature=0.0).strip()

    # The assistant queries issued from inside a solution ("sort the receptacles...",
    # "the identifier of the object?") are natural-language questions; they go through
    # the chat interface (the reference's gpt-3.5 variant wraps them as one user message)
    # with a format-only system line, because the instruct model otherwise prefixes
    # its list with prose and `literal_eval` in the generated code fails.
    ASSISTANT_SYSTEM = ("You are an assistant to a household robot. Answer with exactly what is asked "
                        "(a Python list or a number) and nothing else: no explanation, no code fences.")

    def ask_assistant(self, prompt):
        if self._stale():
            raise _AttemptEnded()
        out = self.llm.chat([{"role": "system", "content": self.ASSISTANT_SYSTEM},
                             {"role": "user", "content": str(prompt).strip()}],
