def extract_receptacles_and_task(text):
    receptacles = re.findall(r"\b\w+ \d+\b", text)
    task = re.search(r"Your task is to:.*", text).group(0)
    return receptacles, task


def extract_answers(text, markers):
    answers = []
    for i, marker in enumerate(markers):
        if i < len(markers) - 1:
            next_marker = markers[i + 1]
            pattern = fr"{re.escape(marker)}\s*([\s\S]*?)\n*{re.escape(next_marker)}"
        else:
            pattern = fr"{re.escape(marker)}\s*([\s\S]*)"
        answer = re.search(pattern, text)
        if answer:
            answers.append(answer.group(1).strip())
        else:
            answers.append('Not found')
    return answers


def get_first_digit(input_string):
    match = re.search(r'\d', input_string)
    return int(match.group()) if match else None


def modify_header(checkpoint):
    if not checkpoint:
        return 'def solution(agent, start_from=1):'
    load_checkpoint = ''
    for k, v in checkpoint.items():
        if k not in ['agent', 'start_from']:
            if type(v) == str:
                load_checkpoint += f', {k}="{v}"'
            else:
                load_checkpoint += f', {k}={v}'
    return f'def solution(agent, start_from{load_checkpoint}):'


def formalize(solution_func):
    return solution_func.replace('CD', 'cd').replace('solution(agent)', '').replace('<EOC>', '') \
        .replace('print("Task completed successfully!")', '').replace('print(agent.report())', '') \
        .replace('receptacles =', '# receptacles =')


def wrap_solution(response):
    # Completion-boundary handling for an open model served as a raw completion: GPT-3
    # stopped after the function, while the open instruct model keeps writing ("solution(agent)", notes,
    # another task). Keep the text from the first `def solution(` line up to the first
    # following column-0 line; a response without a def is wrapped as in the reference.
    lines = response.split('\n')
    start = next((i for i, l in enumerate(lines) if l.startswith('def solution(')), None)
    if start is not None:
        end = next((i for i in range(start + 1, len(lines))
                    if lines[i].strip() and not lines[i].startswith((' ', '\t'))), len(lines))
        return '\n'.join(lines[start:end]).rstrip()
    return '''
    def solution(agent, start_from=1):
        <solution>
    '''.strip().replace('<solution>', response) if not response.startswith('def solution(agent, start_from=1):') else response


